45: // description into the repo (a real file, a real session), then commit it —
46: // the checkpoint is the rollback anchor before the fix is applied.
47: // If agy or git is unavailable, the fix records checkpoint: null with the
48: // reason — honest, never faked.
49: function entireCheckpoint(label, incidentId) {
50:   try {
51:     // 1. Real agent session: agy writes the repair plan file (its own reasoning, recorded)
52:     const planFile = join(ROOT, 'fixes', `${incidentId}-repair-plan.md`);
53:     const prompt = `Create the file ${planFile} with a one-line heading 'Repair plan for ${incidentId}: ${label}' and nothing else. Make only that change.`;
54:     execFileSync('agy', ['-p', prompt], {
55:       cwd: ROOT, timeout: 120000, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'],
56:     });
57:     // 2. Commit it: the checkpoint anchor is born (session + commit)
58:     execFileSync('git', ['add', planFile], { cwd: ROOT, encoding: 'utf8' });
59:     execFileSync('git', ['commit', '-m', `Entire pre-fix anchor: ${label} (${incidentId})`], { cwd: ROOT, encoding: 'utf8' });
60:     // 3. Read the checkpoint this just created
61:     const out = execFileSync('entire', ['checkpoint', 'list'], {
62:       cwd: ROOT, timeout: 30000, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'],
63:       env: { ...process.env, ENTIRE_TOKEN_STORE: 'file', PATH: process.env.PATH },
64:     });
65:     const m = out.match(/●\s+([0-9A-Z]{20,})/);
66:     return { ok: true, id: m ? m[1] : null, raw: out.slice(0, 300) };
67:   } catch (e) {
68:     return { ok: false, reason: String(e.message || e).slice(0, 200) };
69:   }
70: }
